import{_ as a,c as t,o as e,ah as p}from"./chunks/framework.l36K22_3.js";const n="/assets/sanya1.OrhXNsRd.jpg",o="/assets/sanya2.C9QiPszQ.jpg",i="/assets/sanya3.DSzkTH82.jpg",l="/assets/sanya4.BMe8ypYb.jpg",r="/assets/sanya5.BSctTsP3.jpg",f=JSON.parse('{"title":"三亚跟团行","description":"清明前后，跟可爱的同事们去了一趟海南三亚游玩，而且回来之后，还很不幸的感冒了，一直鼻涕流个不停，才发现，自个儿的身体是那个虚呀，所以，也提醒自己并倡导大家，要多多锻炼身体呀。 这次三亚之旅呢，是跟团去的，玩的地方有，博鳌、西岛、玉带滩、热带...","frontmatter":{"title":"三亚跟团行","date":"2014-04-08T00:00:00.000Z","category":"travel","tags":["旅行"],"slug":"sanya-with-mass-line","layout":"blog-post","description":"清明前后，跟可爱的同事们去了一趟海南三亚游玩，而且回来之后，还很不幸的感冒了，一直鼻涕流个不停，才发现，自个儿的身体是那个虚呀，所以，也提醒自己并倡导大家，要多多锻炼身体呀。 这次三亚之旅呢，是跟团去的，玩的地方有，博鳌、西岛、玉带滩、热带..."},"headers":[],"relativePath":"blog/sanya-with-mass-line.md","filePath":"blog/posts/travel/sanya-with-mass-line.md","lastUpdated":1788854523000}'),_={name:"blog/sanya-with-mass-line.md"};function c(g,s,m,d,y,h){return e(),t("div",null,s[0]||(s[0]=[p('<p>清明前后，跟可爱的同事们去了一趟海南三亚游玩，而且回来之后，还很不幸的感冒了，一直鼻涕流个不停，才发现，自个儿的身体是那个虚呀，所以，也提醒自己并倡导大家，要多多锻炼身体呀。</p><p>这次三亚之旅呢，是跟团去的，玩的地方有，博鳌、西岛、玉带滩、热带植物园、椰田古寨、亚龙湾海底世界——沙滩漫步、天涯海角、兰花大世界等等。</p><p>当然，既然跟团了，那自己也就不用做什么功课了，跟着导游走就是了。不过，下次如果有机会再去的话，那我想我肯定是要自助游了。要不然真像有位导游说的，花钱买罪受咯。</p><p>玩过这些地方，当然也清楚哪些地好玩，哪些并不是很有意思。</p><p>像兰花大世界就真心没啥兴趣，当然，对于爱兰懂兰的朋友来说又是例外了。</p><p>到三亚，当然是以看海玩水为主吧，但是，记得做好防晒措施，不然，别像有些人回来之后，整个脸都肿起来了，那真是后遗症相当厉害了。</p><p>我能不说，这次是我第一次坐飞机，第一次这么近距离接触海吧，而且，我也终于想通了在海上逃难的人为什么会渴死，因为，海水真的很咸，很咸。</p><p>好吧，不多说了，上几张游玩照片给大家 see：</p><p><img src="'+n+'" alt="" loading="lazy"><img src="'+o+'" alt="" loading="lazy"><img src="'+i+'" alt="" loading="lazy"><img src="'+l+'" alt="" loading="lazy"><img src="'+r+'" alt="" loading="lazy"></p><br><br>',11)]))}const b=a(_,[["render",c]]);export{f as __pageData,b as default};
